 "A line each, with a check beside it.": "Una línea cada uno, con una marca al lado.",
 "A line from you (optional)": "Unas palabras tuyas (opcional)",
 "A line of your own above the footer, such as a returns note. The address and links stay.": "Una línea tuya encima del pie, como una nota de devoluciones. La dirección y los enlaces se mantienen.",
 "A line of your own at the foot of the email. The links and the note on why it came stay.": "Una línea tuya al pie del email. Los enlaces y la nota de por qué llegó se mantienen.",
 "A line or two about them.": "Una o dos líneas sobre esta persona.",
 "A line or two under the title on the blog page. Left empty, the post's first words are used.": "Una o dos líneas bajo el título en la página del blog. Si lo dejas vacío, se usan las primeras palabras de la entrada.",
 "A line over the header with how much more gets free shipping.": "Una línea sobre la cabecera con cuánto falta para el envío gratis.",
 "A line under it (optional)": "Una línea debajo (opcional)",
