 "A link drawn as a button": "Un enlace con forma de botón",
 "A link is not an address yet. Fix it or remove it.": "Un enlace aún no es una dirección. Corrígelo o quítalo.",
 "A link is waiting for them. See it in Team.": "Hay un enlace esperándolos. Míralo en Equipo.",
 "A link needs a full web address, like https://example.com/guide.": "Un enlace necesita una dirección web completa, como https://example.com/guide.",
 "A link they get right away: a free guide, a video, a group chat.": "Un enlace que reciben al momento: una guía gratis, un video, un chat de grupo.",
 "A live call every week": "Una llamada en directo cada semana",
 "A livestream link starts with https://": "Un enlace de directo empieza por https://",
 "A location": "Una ubicación",
 "A location is any place that holds your stock: your home, a warehouse, a fulfillment center, or a supplier who ships for you.": "Una ubicación es cualquier lugar que guarda tu stock: tu casa, un almacén, un centro logístico o un proveedor que envía por ti.",
 "A market is a group of countries. Give it a currency and its visitors see your prices converted at the day's European Central Bank rate, with the rounding you pick.": "Un mercado es un grupo de países. Dale una moneda y sus visitantes verán tus precios convertidos al tipo del día del Banco Central Europeo, con el redondeo que elijas.",
 "A measurement, converted between cm and in": "Una medida, convertida entre cm e in",
 "A meeting link starts with https://": "Un enlace de reunión empieza por https://",
 "A member muted or banned here can still read the community and its chat. Reports of messages are in Moderation.": "Un miembro silenciado o expulsado aquí puede seguir leyendo la comunidad y su chat. Las denuncias de mensajes están en Moderación.",
 "A mix is fine. Each location says who ships from it, and each product says which location it ships from.": "Una mezcla está bien. Cada ubicación dice quién envía desde ella, y cada producto dice desde qué ubicación se envía.",
 "A mix of these": "Una mezcla de estos",
