 "A name is up to {max} characters.": "El nombre tiene hasta {max} caracteres.",
 "A name, a message or a photo, asked at checkout.": "Un nombre, un mensaje o una foto, que se piden al comprar.",
 "A negative number takes points away.": "Un número negativo quita puntos.",
