 "A new language starts unpublished: translate it, check it, then publish. Anything not translated yet shows in {name}.": "Un idioma nuevo empieza sin publicar: tradúcelo, revísalo y publícalo. Lo que aún no esté traducido se muestra en {name}.",
 "A new link went to {email}. The old one stops working.": "Se envió un enlace nuevo a {email}. El anterior deja de funcionar.",
 "A new look for the whole site": "Un aspecto nuevo para todo el sitio",
