 "A notification on this phone when you make a sale or a payout is ready.": "Un aviso en este teléfono cuando vendes o cuando hay una transferencia lista.",
 "A notification on this phone when you make a sale or a payout is ready. Turn it off in your phone's settings.": "Un aviso en este teléfono cuando vendes o cuando hay una transferencia lista. Desactívalo en los ajustes del teléfono.",
 "A nudge when your first product or payment setup is not done yet.": "Un empujón cuando tu primer producto o la configuración de pagos aún no estén hechos.",
 "A one time price, paid inside the community.": "Un precio único, pagado dentro de la comunidad.",
 "A pack of sessions, booked by link": "Un paquete de sesiones, reservado por enlace",
