 "A photo or a slideshow": "Una foto o un carrusel",
 "A photo the buyer uploads: JPG, PNG or WEBP, up to 10 MB.": "Una foto que sube el comprador: JPG, PNG o WEBP, hasta 10 MB.",
 "A picture": "Una imagen",
 "A picture did not upload. Try again.": "Una imagen no se subió. Inténtalo de nuevo.",
 "A picture, moved": "Una imagen, recolocada",
 "A picture, or an intro video, at the top. It also shows on your card in Explore.": "Una imagen o un vídeo de presentación arriba. También aparece en tu tarjeta en Explorar.",
 "A place for your members: posts, chat, Learn and live events. Free, paid every month or year, or by invite only.": "Un lugar para tus miembros: publicaciones, chat, Aprender y eventos en directo. Gratis, de pago mensual o anual, o solo por invitación.",
 "A place of your own": "Un lugar propio",
 "A portfolio for my wedding and portrait photography with galleries, packages and prices, and a contact form.": "Un portafolio para mi fotografía de bodas y retratos con galerías, paquetes y precios, y un formulario de contacto.",
 "A post on {name}'s blog.": "Una entrada del blog de {name}.",
 "A post, form, player or calendar": "Una publicación, formulario, reproductor o calendario",
 "A price is between $1 and {top}.": "El precio va de 1 $ a {top}.",
 "A print partner makes this when it sells, so there is no stock to count.": "Un socio de impresión lo fabrica cuando se vende, así que no hay stock que contar.",
 "A product": "Un producto",
 "A product in it was deleted. Edit it to fix.": "Se eliminó un producto incluido. Edítala para arreglarlo.",
 "A product in this offer is no longer in your store, so the offer can't apply.": "Un producto de esta oferta ya no está en tu tienda, así que la oferta no puede aplicarse.",
 "A product taxed differently here, like books or food at a reduced rate.": "Un producto que tributa distinto aquí, como libros o comida a tipo reducido.",
 "A product that is no longer published": "Un producto que ya no está publicado",
 "A product that was deleted": "Un producto que se eliminó",
 "A product you archive is kept here, off your page, until you restore it.": "Un producto que archivas se guarda aquí, fuera de tu página, hasta que lo restaures.",
 "A product you sell": "Un producto que vendes",
 "A product, payouts, then your link.": "Un producto, los pagos y luego tu enlace.",
 "A program is modules of lessons: videos, notes and files. Members find it under Learn.": "Un programa son módulos de lecciones: vídeos, notas y archivos. Los miembros lo encuentran en Aprender.",
 "A program of lessons, or a course you already sell.": "Un programa de lecciones o un curso que ya vendas.",
 "A public https address": "Una dirección https pública",
 "A public https address of the design, a PDF or PNG at print size.": "Una dirección https pública del diseño, un PDF o PNG al tamaño de impresión.",
 "A push from GitHub": "Un push desde GitHub",
 "A push to {branch} wasn't brought in": "No se trajo un push a {branch}",
 "A push to {pushed} wasn't brought in. This site follows {branch}.": "Un push a {pushed} no se trajo. Este sitio sigue {branch}.",
 "A question": "Una pregunta",
 "A quick introduction on the community's card, up to 160 characters.": "Una presentación breve en la tarjeta de la comunidad, hasta 160 caracteres.",
 "A reason you delete stays on the returns and refunds that already used it.": "Un motivo que elimines se mantiene en las devoluciones y reembolsos que ya lo usaron.",
 "A refund window is a whole number of hours, up to {value}.": "El plazo de reembolso es un número entero de horas, hasta {value}.",
 "A revoked invite stops working at once.": "Una invitación revocada deja de funcionar al momento.",
 "A row of your latest posts": "Una fila con tus últimas publicaciones",
 "A row of your products, always up to date": "Una fila con tus productos, siempre al día",
 "A sale": "Una venta",
 "A sales channel is a place your products are listed. Storelib runs three: your online store, your creator page and Explore.": "Un canal de venta es un lugar donde aparecen tus productos. Storelib gestiona tres: tu tienda online, tu página de creador y Explorar.",
 "A sample membership, drawn the way the real email is sent. The real email has the member's own plan, price and dates.": "Una membresía de ejemplo, dibujada tal como se envía el email real. El email real tiene el plan, el precio y las fechas del miembro.",
 "A sample order with your store's name. The real email has the buyer's own items, address and order.": "Un pedido de ejemplo con el nombre de tu tienda. El correo real lleva los artículos, la dirección y el pedido del comprador.",
 "A sample order, drawn the way the real email is sent. The real email has the buyer's own items, address and order.": "Un pedido de ejemplo, dibujado como se envía el email real. El email real tiene los artículos, la dirección y el pedido del comprador.",
 "A sample with your store's name, logo and colour.": "Una muestra con el nombre, el logo y el color de tu tienda.",
 "A save is still going. Leaving now could lose it.": "Aún se está guardando. Si sales ahora, podrías perderlo.",
 "A section you add starts on this scheme.": "Una sección que añadas empieza con este esquema.",
 "A section, in the table of contents": "Una sección, en el índice",
 "A segment": "Un segmento",
 "A service code, like usps_priority. Empty: the cheapest.": "Un código de servicio, como usps_priority. Vacío: el más barato.",
 "A shared folder, a template, a recording. Only members who open the item are sent to it.": "Una carpeta compartida, una plantilla, una grabación. Solo se envía a los miembros que abren el elemento.",
 "A shipping profile is a group of products that ship the same way. Every product starts in the General profile.": "Un perfil de envío es un grupo de productos que se envían de la misma forma. Todos los productos empiezan en el perfil General.",
 "A shipping rate for where you sell, or local pickup.": "Una tarifa de envío para donde vendes, o recogida local.",
 "A short bio about yourself...": "Una bio corta sobre ti...",
 "A short list new members see above the feed for their first 30 days, until they finish it or hide it.": "Una lista corta que los nuevos miembros ven sobre el feed durante sus primeros 30 días, hasta que la terminan o la ocultan.",
 "A site keeps {n} custom tokens at most.": "Un sitio guarda como mucho {n} tokens propios.",
 "A smaller heading": "Un título más pequeño",
 "A space name is up to {max} characters.": "El nombre del espacio tiene hasta {max} caracteres.",
 "A start for a store in {country}. Type your prices, check the days, then press Use this setup. You can change all of it later.": "Un punto de partida para una tienda en {country}. Escribe tus precios, revisa los días y pulsa Usar esta configuración. Puedes cambiarlo todo después.",
 "A step of your own": "Un paso propio",
