 "A video, playing on a loop": "Un vídeo en bucle",
 "A visit is counted when the visitor leaves the page.": "Una visita se cuenta cuando el visitante sale de la página.",
 "A visitor confirms their review from an email before it posts, and it is not marked Verified buyer or counted in your Storelib rating. A buyer who uses the form is sent their own link instead.": "Un visitante confirma su reseña desde un correo antes de que se publique, y no se marca como Comprador verificado ni cuenta en tu valoración de Storelib. Al comprador que usa el formulario se le envía su propio enlace.",
 "A visitor's details are sent only when their cookie choice allows it. Emails and phone numbers go hashed. Test sales are never sent.": "Los datos de un visitante solo se envían cuando su elección de cookies lo permite. Los correos y teléfonos van cifrados con hash. Las ventas de prueba nunca se envían.",
