 "Ask AI: add my TikTok @ana": "Pide a la IA: añade mi TikTok @ana",
 "Ask Storelib": "Preguntar a Storelib",
 "Ask Storelib to step in": "Pedir a Storelib que intervenga",
 "Ask Storelib writes it. Change it after.": "Ask Storelib la escribe. Cámbiala después.",
 "Ask a buyer how it is going, seven days after they bought.": "Pregunta a un comprador qué tal le va, siete días después de comprar.",
 "Ask a few questions first": "Hacer unas preguntas antes",
 "Ask about a product": "Preguntar por un producto",
 "Ask an order": "Pedir a un pedido",
 "Ask an order for a review": "Pedir una reseña a un pedido",
 "Ask buyers for a name, a message or a photo when they buy. You see their answers on the order.": "Pide a los compradores un nombre, un mensaje o una foto al comprar. Verás sus respuestas en el pedido.",
 "Ask for a change": "Pide un cambio",
 "Ask for a change, such as “make the hero taller”. It reads AGENTS.md first.": "Pide un cambio, como “haz el hero más alto”. Lee AGENTS.md primero.",
 "Ask for a first name": "Pedir el nombre",
