 "Asked to join": "Pidió unirse",
 "Asking buyers if they want to hear from you, the way the law in most places expects.": "Preguntar a los compradores si quieren saber de ti, como exige la ley en la mayoría de lugares.",
 "Asking for rates": "Pidiendo tarifas",
 "Aspect Ratio": "Proporción",
