 "Assigned Files": "Archivos asignados",
 "Astrology": "Astrología",
 "At": "A las",
 "At a glance": "De un vistazo",
 "At a time": "A una hora",
 "At checkout": "Al pagar",
 "At checkout Storelib adds the tax your settings above call for, shows it to the buyer, puts it on the receipt and keeps the record here. Nothing has to be set up before you can sell.": "En el pago, Storelib añade el impuesto que indican tus ajustes de arriba, se lo muestra al comprador, lo incluye en el recibo y guarda el registro aquí. No hace falta configurar nada antes de vender.",
 "At checkout Storelib adds the tax your settings below call for, shows it to the buyer, puts it on the receipt and keeps the record here. Nothing has to be set up before you can sell.": "En el pago, Storelib añade el impuesto que indican tus ajustes de abajo, se lo muestra al comprador, lo incluye en el recibo y guarda el registro aquí. No hace falta configurar nada antes de vender.",
 "At checkout Storelib looks at where the buyer is and adds that region's rate. Buyers anywhere else pay no tax.": "En el pago, Storelib mira dónde está el comprador y suma el tipo de esa región. Los compradores de cualquier otro sitio no pagan impuestos.",
 "At checkout the buyer types their address. Storelib finds the zone it falls in and shows that zone's rates. An address in no zone cannot check out, so add every country you ship to.": "En el pago, el comprador escribe su dirección. Storelib encuentra la zona en la que cae y muestra sus tarifas. Una dirección sin zona no puede pagar, así que añade todos los países a los que envías.",
 "At least 7 days. A card is taken at sign up and charged when the trial ends, unless they cancel.": "Mínimo 7 días. Se pide una tarjeta al registrarse y se cobra cuando termina la prueba, salvo que cancelen.",
 "At most {amount} can go back.": "Se pueden devolver como máximo {amount}.",
 "At most {value}.": "Como máximo {value}.",
 "At or below it is low, for every product without its own line (set in the product's Inventory card).": "Igual o por debajo es bajo, para todo producto sin umbral propio (se fija en la tarjeta Inventario del producto).",
 "At the check": "En la comprobación",
 "At the end of the period": "Al final del periodo",
