 "Automatic": "Automático",
 "Automatic link preview": "Vista previa automática del enlace",
 "Automatic translation isn't set up on Storelib yet. You can still write each translation yourself.": "La traducción automática aún no está configurada en Storelib. Puedes escribir cada traducción tú mismo.",
 "Automatic translation keeps these words as written, or always uses your translation. Translations you write yourself are never changed.": "La traducción automática deja estas palabras tal cual, o usa siempre tu traducción. Las traducciones que escribes tú nunca se cambian.",
 "Automatic translation leaves product titles as you wrote them. You can still translate a title yourself on the product's Translations card.": "La traducción automática deja los títulos de productos tal como los escribiste. Puedes traducir un título tú mismo en la tarjeta Traducciones del producto.",
 "Automatic updates are not on yet": "Las actualizaciones automáticas aún no están activadas",
 "Automatic updates on again": "Actualizaciones automáticas activadas de nuevo",
 "Automatic updates paused": "Actualizaciones automáticas en pausa",
 "Automatic updates paused for this package": "Actualizaciones automáticas en pausa para este paquete",
 "Automatic updates turn on when Storelib's tracking is set up. Until then, orders keep the statuses you set and the carrier's tracking link, and buyers get the same emails when you change a status.": "Las actualizaciones automáticas se activan cuando se configure el seguimiento de Storelib. Hasta entonces, los pedidos mantienen los estados que pongas y el enlace de seguimiento del transportista, y los compradores reciben los mismos correos cuando cambias un estado.",
 "Automatic updates turn on when Storelib's tracking is set up. Until then, set the status from the menu.": "Las actualizaciones automáticas se activan cuando se configure el seguimiento de Storelib. Hasta entonces, pon el estado desde el menú.",
