 "Changing it signs you out on your other devices.": "Al cambiarla se cierra la sesión en tus otros dispositivos.",
 "Changing the currency asks what happens to your prices: keep the numbers (100 EUR becomes 100 USD) or convert them at the day's exchange rate. Orders already placed keep their own currency.": "Al cambiar la moneda se te pregunta qué pasa con tus precios: mantener los números (100 EUR pasa a 100 USD) o convertirlos al tipo de cambio del día. Los pedidos ya hechos mantienen su moneda.",
