 "Describe what shows the sale was real: what the buyer bought, that the files were delivered or downloaded, and any messages with them. Plain words are best.": "Describe lo que demuestra que la venta fue real: qué compró el comprador, que los archivos se entregaron o descargaron, y cualquier mensaje con él. Mejor con palabras sencillas.",
