 "Imported reviews are marked Imported. They can show on your website, but they never get the Verified purchase label and never count in your Storelib rating.": "Las reseñas importadas se marcan como Importadas. Pueden aparecer en tu sitio web, pero nunca llevan la etiqueta Compra verificada ni cuentan en tu valoración de Storelib.",
