 "Importing…": "Importando…",
 "Improved loading skeleton structures for Explore, Analytics, and Upgrade pages to better match actual page layouts.": "Los esqueletos de carga de Explorar, Analíticas y Planes se parecen más a las páginas reales.",
 "Improved settings page with smoother sticky save bar animations, toast notifications, and faster tab navigation with skeleton loading.": "Configuración con una barra de guardado más fluida, avisos y cambio de pestaña más rápido con carga progresiva.",
 "Improvement": "Mejora",
 "In 17TRACK, Settings > Webhook: add this address. 17TRACK signs updates with your API key. Without it Storelib checks every few hours.": "En 17TRACK, Settings > Webhook: añade esta dirección. 17TRACK firma las actualizaciones con tu clave de API. Sin ello, Storelib comprueba cada pocas horas.",
 "In AfterShip, Settings > Webhooks: add this address, then paste its webhook secret under Change key, so updates arrive the moment they happen. Without it Storelib checks every few hours.": "En AfterShip, Settings > Webhooks: añade esta dirección y pega su secreto de webhook en Cambiar clave, para que las actualizaciones lleguen al momento. Sin ello, Storelib comprueba cada pocas horas.",
 "In Brevo, open SMTP and API, API keys.": "En Brevo, abre SMTP y API, Claves de API.",
 "In Canva, press Share, then Embed, and paste the smart embed link here.": "En Canva, pulsa Compartir y luego Insertar, y pega aquí el enlace de inserción inteligente.",
 "In Flodesk, open Account settings, Integrations, API keys.": "En Flodesk, abre Ajustes de la cuenta, Integraciones, Claves de API.",
 "In Gelato, Developer › Webhooks, add this address for order status and tracking code updates:": "En Gelato, Developer › Webhooks, añade esta dirección para recibir el estado del pedido y el código de seguimiento:",
 "In Gelato, Developer › Webhooks, add this address for order status and tracking updates.": "En Gelato, Developer › Webhooks, añade esta dirección para recibir el estado de los pedidos y el seguimiento.",
 "In Google Ads, open Goals › Conversions › New conversion action › Import › Google Analytics 4 and pick them.": "En Google Ads, abre Objetivos › Conversiones › Nueva acción de conversión › Importar › Google Analytics 4 y elígelos.",
 "In Google Analytics, Reports › Realtime shows a visit within a minute. The “Data collection isn't active” notice on your stream can take up to 48 hours to go away.": "En Google Analytics, Informes › Tiempo real muestra una visita en menos de un minuto. El aviso «La recogida de datos no está activa» de tu flujo puede tardar hasta 48 horas en desaparecer.",
 "In Google Analytics, open Admin › Product links › Google Ads links and link your Ads account.": "En Google Analytics, abre Administrar › Enlaces de productos › Enlaces de Google Ads y enlaza tu cuenta de Ads.",
 "In Gumroad, open Settings › Advanced.": "En Gumroad, abre Settings › Advanced.",
 "In Kit, open Settings, Developer.": "En Kit, abre Ajustes, Desarrollador.",
 "In Mailchimp, open Profile, Extras, API keys.": "En Mailchimp, abre Perfil, Extras, Claves de API.",
 "In MailerLite, open Integrations, API.": "En MailerLite, abre Integraciones, API.",
