 "Of the people who visited, how many opened a product, added it to the cart or pressed Buy, started a checkout, and how many orders came in. Each step is a share of the one before; the step that loses the most people is marked in red.": "De las personas que visitaron, cuántas abrieron un producto, lo añadieron al carrito o pulsaron Comprar, iniciaron el pago, y cuántos pedidos llegaron. Cada paso es una parte del anterior; el paso que más personas pierde se marca en rojo.",
 "Of the people who visited, how many opened a product, how many started a checkout, and how many orders came in. Each step is shown as a share of the one before.": "De las personas que visitaron, cuántas abrieron un producto, cuántas empezaron un pago y cuántos pedidos llegaron. Cada paso se muestra como parte del anterior.",
 "Of this period's physical orders, the share that has been shipped or delivered, and how long a parcel waited from payment to shipped.": "De los pedidos físicos de este periodo, la parte ya enviada o entregada, y cuánto esperó un paquete desde el pago hasta el envío.",
 "Of views": "De las visitas",
