 "Off keeps the market and sells to its countries as your home market.": "Desactivado mantiene el mercado y vende a sus países como tu mercado principal.",
 "Off keeps this page out of Google and out of your sitemap.": "Desactivado, esta página queda fuera de Google y de tu sitemap.",
 "Off keeps this post out of Google and out of your sitemap.": "Desactivado, esta entrada queda fuera de Google y de tu sitemap.",
 "Off one of it.": "De una unidad.",
 "Off sale": "Fuera de venta",
 "Off the product it offers.": "De descuento en el producto que ofrece.",
 "Off to keep stock here without shipping from it.": "Desactívalo para guardar stock aquí sin enviar desde aquí.",
 "Off to keep this location without shipping from it or offering pickup.": "Desactívalo para mantener esta ubicación sin enviar desde ella ni ofrecer recogida.",
 "Off topic": "Fuera de tema",
 "Off, buyers pay your prices and nothing more.": "Desactivado, los compradores pagan tus precios y nada más.",
 "Off, each order is made in CJ unpaid, and waits until you pay it there. On, it is confirmed and paid from your CJ balance as soon as your buyer pays.": "Desactivado, cada pedido se crea en CJ sin pagar y espera a que lo pagues allí. Activado, se confirma y se paga con tu saldo de CJ en cuanto paga el comprador.",
 "Off, each order waits in {name} as a draft until you approve it there, and {name2} charges you only then. On, it is made and charged as soon as it is paid.": "Desactivado, cada pedido espera en {name} como borrador hasta que lo apruebes allí, y {name2} te cobra solo entonces. Activado, se crea y se cobra en cuanto se paga.",
 "Off, it follows your store setting: {value}{value2}.": "Desactivado, sigue el ajuste de tu tienda: {value}{value2}.",
 "Off, it stays on your list and on your products, and isn't offered for new ones.": "Desactivado, sigue en tu lista y en tus productos, y no se ofrece para los nuevos.",
 "Off, its countries see your home market.": "Desactivado, sus países ven tu mercado principal.",
 "Off, the order page has no return button.": "Desactivado, la página del pedido no tiene botón de devolución.",
 "Off. Buyers do not see it until you turn it on.": "Desactivada. Los compradores no la ven hasta que la actives.",
