 "Only Storelib sees this.": "Solo Storelib lo ve.",
 "Only YouTube and Vimeo links can be added as a video.": "Solo se pueden añadir como vídeo enlaces de YouTube y Vimeo.",
 "Only a community anyone can join is shown. Change that under Access and prices.": "Solo se muestra una comunidad a la que cualquiera puede unirse. Cámbialo en Acceso y precios.",
 "Only approved translations show, and only once a language is published. Anything not translated yet shows in your default language, never blank.": "Solo se muestran traducciones aprobadas, y solo cuando el idioma está publicado. Lo que aún no esté traducido se muestra en tu idioma predeterminado, nunca en blanco.",
 "Only buyers in {country} can order. You can add more places later.": "Solo pueden pedir compradores en {country}. Puedes añadir más lugares después.",
 "Only buyers who asked for your news": "Solo compradores que pidieron tus noticias",
 "Only changes the builder. In another language, the sidebar edits that language's text.": "Solo cambia el editor. En otro idioma, la barra lateral edita el texto de ese idioma.",
 "Only changes what you see here. Visitors choose their own.": "Solo cambia lo que ves aquí. Los visitantes eligen los suyos.",
 "Only for collections": "Solo para colecciones",
 "Only for me": "Solo para mí",
 "Only if {phrase}": "Solo si {phrase}",
 "Only its author can add files and videos to this post.": "Solo la persona que escribió la publicación puede añadir archivos y vídeos.",
 "Only links and images go in a group.": "En un grupo solo van enlaces e imágenes.",
 "Only members ever see Learn. This decides which of them can open the lessons.": "Solo los miembros ven Aprender. Esto decide cuáles de ellos pueden abrir las lecciones.",
 "Only members ever see Learn. This decides which of them open the lessons.": "Solo los miembros ven Aprender. Esto decide quiénes de ellos abren las lecciones.",
 "Only members ever see the Library. This decides which of them open it.": "Solo los miembros ven la Biblioteca. Esto decide cuáles de ellos lo abren.",
 "Only members on the tiers you pick.": "Solo los miembros de los niveles que elijas.",
 "Only on orders over": "Solo en pedidos de más de",
