 "Only orders delivered to these countries. Pickups can always pay in cash.": "Solo pedidos entregados en estos países. Las recogidas siempre pueden pagarse en efectivo.",
 "Only orders placed after you turn the app on are asked. Buyers who turned review emails off, or already reviewed, are never asked.": "Solo se pide en pedidos hechos después de activar la app. Nunca se pide a compradores que desactivaron los correos de reseñas o que ya opinaron.",
