 "Optional. Drag to reorder images.": "Opcional. Arrastra para reordenar las imágenes.",
 "Optional. Each paid order for this product is emailed here with the items and address. Empty: you pass orders on yourself.": "Opcional. Cada pedido pagado de este producto se envía aquí por correo con los artículos y la dirección. Vacío: pasas tú los pedidos.",
 "Optional. Empty: always free.": "Opcional. Vacío: siempre gratis.",
 "Optional. How to measure, or how it fits.": "Opcional. Cómo medir o cómo queda.",
 "Optional. Labels and return emails use it.": "Opcional. Lo usan las etiquetas y los correos de devolución.",
 "Optional. Leave it empty to always charge.": "Opcional. Déjalo vacío para cobrar siempre.",
 "Optional. Listed countries see and pay in their currency. Everyone else sees {currency}.": "Opcional. Los países de la lista ven y pagan en su moneda. Los demás ven {currency}.",
 "Optional. Put {tracking} where the number goes.": "Opcional. Pon {tracking} donde va el número.",
 "Optional. The code after # on the order.": "Opcional. El código tras # en el pedido.",
