 "Optional. Visitors from other countries see your prices in their currency and pay in it.": "Opcional. Los visitantes de otros países ven tus precios en su moneda y pagan en ella.",
 "Optional. Visitors in the countries you list see prices in that currency and pay in it. Everyone else sees {currency}. Anyone can switch with your website's currency selector.": "Opcional. Los visitantes de los países que indiques ven los precios en esa moneda y pagan en ella. Los demás ven {currency}. Cualquiera puede cambiarla con el selector de moneda de tu web.",
 "Optional. Visitors in these countries see your prices in their currency, can switch with your website's currency selector, and pay in it.": "Opcional. Los visitantes de estos países ven tus precios en su moneda, pueden cambiarla con el selector de moneda de tu web y pagan en ella.",
