 "They need a database update (SQL part 283) before they can be used.": "Necesitan una actualización de la base de datos (parte SQL 283) antes de poder usarse.",
 "They need the Forms database update (SQL parts 372 and 375 in Admin › SQL updates). Everything else keeps working.": "Necesitan la actualización de la base de datos de Formularios (partes SQL 372 y 375 en Admin › Actualizaciones SQL). Todo lo demás sigue funcionando.",
 "They pay in a window on your page, like joining a community. For downloads and courses.": "Pagan en una ventana en tu página, como al unirse a una comunidad. Para descargas y cursos.",
 "They pick a reason from your list and the items. You get an email and approve or decline it from the order.": "Elige un motivo de tu lista y los artículos. Recibes un correo y lo apruebas o rechazas desde el pedido.",
