 "This program opens at {value}. You are at level {current}. Levels come from points for taking part in the community.": "Este programa se abre en {value}. Estás en el nivel {current}. Los niveles vienen de los puntos por participar en la comunidad.",
 "This publish will not be backed up. Run supabase/sql/RUN_THEME_BACKUPS.sql once to turn backups on.": "Esta publicación no tendrá copia de seguridad. Ejecuta supabase/sql/RUN_THEME_BACKUPS.sql una vez para activar las copias.",
 "This records the cash you gave back. Nothing is sent to a card, and the buyer gets an email about it.": "Esto registra el efectivo que devolviste. No se envía nada a una tarjeta y el comprador recibe un correo al respecto.",
 "This replaces {domain}. For 30 days {domain2} sends its visitors on to {clean}, then it stops. Press Replace to go ahead.": "Esto sustituye a {domain}. Durante 30 días {domain2} envía a sus visitantes a {clean} y después se detiene. Pulsa Sustituir para continuar.",
 "This review is already on your store.": "Esta reseña ya está en tu tienda.",
 "This sale cannot be refunded.": "Esta venta no se puede reembolsar.",
 "This section shows {max} at most. Remove one to add another.": "Esta sección muestra {max} como máximo. Quita una para añadir otra.",
 "This setting takes a {what}.": "Este ajuste admite un {what}.",
 "This site follows {branch} now.": "Este sitio ahora sigue {branch}.",
 "This site follows {value}. Follow {branch} instead to bring it in now, or merge it into {value2} on GitHub.": "Este sitio sigue {value}. Sigue {branch} en su lugar para traerlo ahora, o fusiónalo en {value2} en GitHub.",
 "This site follows {value}. Merge it into {value2} on GitHub to bring it in.": "Este sitio sigue {value}. Fusiónalo en {value2} en GitHub para traerlo.",
 "This site uses its own copy of this built-in section. Other sites keep Storelib's.": "Este sitio usa su propia copia de esta sección integrada. Los demás sitios mantienen la de Storelib.",
 "This store has no communities yet. The owner makes them.": "Esta tienda aún no tiene comunidades. Las crea el propietario.",
 "This text": "Este texto",
 "This text appears on your customer's bank statement to identify who charged them.": "Este texto aparece en el extracto bancario del cliente para identificar quién le cobró.",
 "This text appears on your customers' bank statements. It helps them identify the charge. Format: \"(Your Name) - STORELIB\". Only your name can be changed. Max 22 characters total.": "Este texto aparece en los extractos bancarios de tus clientes y les ayuda a reconocer el cargo. Formato: \"(Tu nombre) - STORELIB\". Solo se puede cambiar tu nombre. Máximo 22 caracteres en total.",
