 "To GitHub": "A GitHub",
 "To count stock, have it fulfilled from one of your own locations.": "Para contar el stock, haz que se prepare desde una de tus ubicaciones.",
 "To days": "Hasta (días)",
 "To do": "Pendiente",
 "To do ({count})": "Pendiente ({count})",
 "To hand it over in person, turn on local pickup in Settings › Shipping.": "Para entregarlo en persona, activa la recogida local en Ajustes › Envíos.",
 "To keep your payouts going, Stripe asks for this now{value}. It takes a minute.": "Para que sigan tus transferencias, Stripe te lo pide ahora{value}. Tarda un minuto.",
 "To make one link stand out, use the sparkle button on that link in Links.": "Para destacar un enlace, usa el botón de destellos en ese enlace en Enlaces.",
 "To move a photo or video, press Space or Enter on it, then the arrow keys. Press Space or Enter again to drop it, or Escape to put it back. The first is the thumbnail.": "Para mover una foto o vídeo, pulsa Espacio o Intro sobre él y luego las flechas. Pulsa Espacio o Intro otra vez para soltarlo, o Escape para devolverlo. El primero es la miniatura.",
 "To move a picture or video, press Space or Enter on it, then the arrow keys. Press Space or Enter again to drop it, or Escape to put it back. The first is shown first.": "Para mover una imagen o un vídeo, pulsa Espacio o Intro sobre él y luego las flechas. Pulsa Espacio o Intro otra vez para soltarlo, o Escape para devolverlo a su sitio. El primero se muestra primero.",
 "To move a question, press Space or Enter on its handle, then the up and down arrow keys. Press Space or Enter again to drop it, or Escape to put it back.": "Para mover una pregunta, pulsa Espacio o Intro en su asa y luego las flechas arriba y abajo. Pulsa Espacio o Intro otra vez para soltarla, o Escape para devolverla.",
 "To move a space, press Enter on its handle, then the arrow keys. Press Enter again to drop it, or Escape to put it back.": "Para mover un espacio, pulsa Intro en su asa y luego las flechas. Pulsa Intro otra vez para soltarlo, o Escape para devolverlo a su sitio.",
 "To move an item, press Enter on its handle, then the arrow keys. Press Enter again to drop it, or Escape to put it back.": "Para mover un elemento, pulsa Intro en su asa y luego las flechas. Pulsa Intro otra vez para soltarlo, o Escape para devolverlo a su sitio.",
 "To move an option, press Space on its handle, then the up and down arrow keys, then Space again.": "Para mover una opción, pulsa Espacio en su asa, luego las flechas arriba y abajo, y Espacio otra vez.",
 "To send a product here: in the product, choose Print on demand and the {value} location, and give each variant the same SKU it has in {name}.": "Para enviar un producto aquí: en el producto, elige Impresión bajo demanda y la ubicación {value}, y da a cada variante el mismo SKU que tiene en {name}.",
 "To send a product here: in the product, choose {value} and the {value2} location, then match each variant to {name}'s below.": "Para enviar un producto aquí: en el producto, elige {value} y la ubicación {value2}, y luego empareja cada variante con las de {name} abajo.",
