 "Visitors": "Visitantes",
 "Visitors are matched by the country they browse from, and can change it with the currency or country selector. Their choice is remembered.": "Los visitantes se asignan por el país desde el que navegan y pueden cambiarlo con el selector de moneda o país. Su elección se recuerda.",
 "Visitors are matched by the country they browse from, and can change it with the currency selector. Their choice is remembered.": "Los visitantes se asignan por el país desde el que navegan y pueden cambiarlo con el selector de moneda. Su elección se recuerda.",
 "Visitors buy it through Storelib checkout. Anyone who owns it sees what is below.": "Los visitantes lo compran con el pago de Storelib. Quien lo tenga ve lo que hay abajo.",
 "Visitors by country": "Visitantes por país",
 "Visitors by the system of their device, with its share of all visitors. Read from the browser's signature, and from its platform hint where the signature is vague.": "Visitantes según el sistema de su dispositivo, con su parte del total. Se lee de la firma del navegador, y de su indicación de plataforma cuando la firma es vaga.",
 "Visitors can also choose": "Los visitantes también pueden elegir",
 "Visitors confirm before it opens": "Los visitantes confirman antes de abrirlo",
 "Visitors get this link only after their response is saved. It never appears in the page.": "Los visitantes reciben este enlace solo después de que se guarde su respuesta. Nunca aparece en la página.",
 "Visitors go to {goesTo} for 30 days, then it stops.": "Los visitantes van a {goesTo} durante 30 días y después se detiene.",
 "Visitors in the EU, the UK and Switzerland are counted in full once they accept cookies; before that Google gets a cookieless ping.": "Los visitantes de la UE, el Reino Unido y Suiza se cuentan del todo cuando aceptan las cookies; antes, Google recibe un ping sin cookies.",
 "Visitors may see a different order depending on their location or preferences.": "Los visitantes pueden ver otro orden según su ubicación o preferencias.",
 "Visitors open the course page, where they can buy it.": "Los visitantes abren la página del curso, donde pueden comprarlo.",
 "Visitors open your website in your default language and store currency, and switch with your theme's own selectors.": "Los visitantes abren tu web en tu idioma predeterminado y la moneda de la tienda, y cambian con los selectores de tu tema.",
 "Visitors pay this product's price at checkout after choosing a time. Paying confirms the booking, and the time is held for 30 minutes until then.": "Los visitantes pagan el precio de este producto al finalizar la compra después de elegir una hora. El pago confirma la reserva y la hora se guarda 30 minutos hasta entonces.",
 "Visitors pick a time before answering. For Calendly or another booking page, use a button action instead.": "Los visitantes eligen una hora antes de responder. Para Calendly u otra página de reservas, usa una acción de botón.",
 "Visitors reach your website at your own address.": "Los visitantes llegan a tu sitio web en tu propia dirección.",
 "Visitors see a placeholder until you publish again.": "Los visitantes verán una página de espera hasta que vuelvas a publicar.",
 "Visitors see a placeholder. {name} was the last one live.": "Los visitantes ven una página de espera. {name} fue el último publicado.",
 "Visitors see it once {title} is published in Products › Collections.": "Los visitantes la verán cuando {title} esté publicada en Productos › Colecciones.",
 "Visitors see the community at this domain. Members sign in on {main}.": "Los visitantes ven la comunidad en este dominio. Los miembros inician sesión en {main}.",
 "Visitors see the last version you published.": "Los visitantes ven la última versión que publicaste.",
 "Visitors see the link once they have booked.": "Los visitantes ven el enlace cuando han reservado.",
 "Visitors see this once {name} is published and public.": "Los visitantes la verán cuando {name} esté publicada y sea pública.",
 "Visitors see your password page until they type the password.": "Los visitantes ven tu página de contraseña hasta que escriben la contraseña.",
 "Visitors start in": "Los visitantes empiezan en",
 "Visitors switch with the language selector. On a Storelib theme it sits under the footer by itself. On a theme you imported from Shopify it is the theme's own selector, turned on in the editor (Show language, usually in the header or footer).": "Los visitantes cambian con el selector de idioma. En un tema de Storelib está bajo el pie, solo. En un tema importado de Shopify es el selector del propio tema, activado en el editor (Show language, normalmente en la cabecera o el pie).",
 "Visitors switch with your theme's language selector. Turn on Show visitors their own language to open a first visit in their browser's language.": "Los visitantes cambian con el selector de idioma de tu tema. Activa Mostrar a los visitantes su propio idioma para abrir la primera visita en el idioma de su navegador.",
 "Visitors who turn motion off see the numbers straight away.": "Quien desactiva el movimiento ve los números al instante.",
 "Visitors who turn off motion on their device see the site without it.": "Quien desactiva el movimiento en su dispositivo ve el sitio sin él.",
 "Visitors: where visits came from, from their connection. Orders: where buyers are, from the order, with their revenue.": "Visitantes: de dónde llegaron las visitas, según su conexión. Pedidos: dónde están los compradores, según el pedido, con sus ingresos.",
 "Visits": "Visitas",
 "Visits by source": "Visitas por origen",
 "Visits older than three days are counted by day, not by hour.": "Las visitas de hace más de tres días se cuentan por día, no por hora.",
 "Visits to your pages, by day.": "Visitas a tus páginas, por día.",
