 "When a shipment is marked as failed: the carrier, or your own delivery, couldn't deliver it.": "Cuando un envío se marca como fallido: el transportista, o tu propia entrega, no pudo entregarlo.",
 "When a store's owner invites you, it shows here and you can open it from your own account.": "Cuando el propietario de una tienda te invite, aparecerá aquí y podrás abrirla desde tu cuenta.",
 "When a ticket is refunded.": "Cuando se reembolsa una entrada.",
 "When buyers can come. Shown at checkout and in the pickup email.": "Cuándo pueden venir los compradores. Se muestra en el pago y en el correo de recogida.",
 "When does Pro pay for itself?": "¿Cuándo se paga solo Pro?",
 "When it comes into view": "Al aparecer en pantalla",
 "When it is sent": "Cuándo se envía",
 "When it pushes to": "Cuando haga push a",
 "When it pushes to {branch}, the change shows here as a draft within seconds.": "Cuando haga push a {branch}, el cambio aparece aquí como borrador en segundos.",
 "When it's marked delivered.": "Cuando se marca como entregado.",
 "When members leave they can say why. Their answers show up here.": "Cuando los miembros se van, pueden decir por qué. Sus respuestas aparecen aquí.",
 "When members report a post, a comment or somebody, it lands here.": "Cuando los miembros denuncian una publicación, un comentario o a alguien, llega aquí.",
 "When memberships end": "Cuándo terminan las membresías",
 "When pressed": "Al pulsar",
 "When returns are on, a buyer sees Request a return on their order page for as many days as your return window.": "Con las devoluciones activadas, el comprador ve Solicitar una devolución en la página de su pedido durante los días de tu plazo de devolución.",
 "When review emails go, and what they say, is under Requests.": "Cuándo salen los emails de reseña, y qué dicen, está en Solicitudes.",
 "When somebody asks to join, they show here with their answers.": "Cuando alguien pida unirse, aparecerá aquí con sus respuestas.",
 "When somebody writes to you through the contact form on your website, the message shows here and in your email.": "Cuando alguien te escribe desde el formulario de contacto de tu sitio web, el mensaje aparece aquí y en tu correo.",
 "When someone buys a ticket to a paid event, with the calendar file.": "Cuando alguien compra una entrada para un evento de pago, con el archivo de calendario.",
 "When someone joins": "Cuando alguien se une",
 "When someone joins a membership you sell on its own, with what they pay and when.": "Cuando alguien se une a una membresía que vendes por separado, con lo que paga y cuándo.",
 "When someone joins a paid plan, with what they pay and when.": "Cuando alguien se une a un plan de pago, con lo que paga y cuándo.",
 "When someone joins your list": "Cuando alguien se une a tu lista",
 "When someone joins, or is let back in.": "Cuando alguien se une o vuelve a ser admitido.",
 "When someone leaves checkout": "Cuando alguien abandona el pago",
 "When someone starts a membership": "Cuando alguien empieza una membresía",
 "When someone taps it": "Cuando alguien lo toca",
 "When the bank declines a renewal. It asks the member to update their card.": "Cuando el banco rechaza una renovación. Pide al miembro que actualice su tarjeta.",
 "When the carrier says it's out for delivery.": "Cuando el transportista dice que está en reparto.",
 "When the items reach you.": "Cuando los artículos te llegan.",
 "When the next scheduled email is sent.": "Cuándo se envía el próximo correo programado.",
 "When the return is closed, with any refund.": "Cuando se cierra la devolución, con el reembolso si lo hay.",
 "When their paid time runs out": "Cuando se acabe el tiempo pagado",
 "When they go": "Cuándo salen",
 "When visitors subscribe, they can download \"": "Cuando los visitantes se suscriben, pueden descargar \"",
 "When will my order arrive?": "¿Cuándo llegará mi pedido?",
 "When you add a product, ship an order or change a setting, it shows up here.": "Cuando añadas un producto, envíes un pedido o cambies un ajuste, aparecerá aquí.",
 "When you approve a request to join": "Cuando apruebas una solicitud para unirse",
 "When you approve a request to join. In a paid community it says how to finish joining.": "Cuando apruebas una solicitud para unirse. En una comunidad de pago explica cómo terminar de unirse.",
 "When you approve a return, with your instructions.": "Cuando apruebas una devolución, con tus instrucciones.",
 "When you cancel a paid event. It says the money is on its way.": "Cuando cancelas un evento de pago. Dice que el dinero está en camino.",
 "When you cancel an order before it ships.": "Cuando cancelas un pedido antes de enviarlo.",
 "When you change the shipping address on an order before it ships.": "Cuando cambias la dirección de envío de un pedido antes de enviarlo.",
 "When you change the tracking number on a shipment that already went out.": "Cuando cambias el número de seguimiento de un envío que ya salió.",
 "When you decline a return, with your note.": "Cuando rechazas una devolución, con tu nota.",
 "When you give someone a ticket.": "Cuando le das una entrada a alguien.",
 "When you invite someone by email": "Cuando invitas a alguien por email",
