 "When you mark a pickup order ready.": "Cuando marcas un pedido de recogida como listo.",
 "When you mark it collected.": "Cuando lo marcas como recogido.",
 "When you mark items shipped, with the tracking.": "Cuando marcas artículos como enviados, con el seguimiento.",
 "When you post an announcement": "Cuando publicas un anuncio",
 "When you publish changes, new and edited text is translated into your other languages within a few minutes. Translations you edit yourself are never replaced.": "Al publicar cambios, el texto nuevo y editado se traduce a tus otros idiomas en unos minutos. Las traducciones que editas tú nunca se reemplazan.",
 "When you published": "Cuando publicaste",
 "When you refund a download, course or membership, here or in Stripe. Its download stops working.": "Cuando reembolsas una descarga, un curso o una membresía, aquí o en Stripe. Su descarga deja de funcionar.",
 "When you refund all or part of an order, here or in Stripe.": "Cuando reembolsas todo o parte de un pedido, aquí o en Stripe.",
 "When you write one. It goes to members who keep community emails on, one a day at most.": "Cuando escribes uno. Llega a los miembros que mantienen activados los emails de la comunidad, uno al día como máximo.",
 "Where": "Dónde",
 "Where answers go": "Adónde van las respuestas",
 "Where are you based?": "¿Dónde estás?",
 "Where buyers collect their orders. For your default location, it's also where return emails tell buyers to send items.": "Dónde recogen los compradores sus pedidos. En tu ubicación predeterminada, también es adonde los correos de devolución dicen que se envíen los artículos.",
 "Where do you ship from?": "¿Desde dónde envías?",
 "Where each order was placed: each of your websites by its name, your OnePage, your creator page, Storelib Explore or a checkout link opened on its own.": "Dónde se hizo cada pedido: cada uno de tus sitios web por su nombre, tu OnePage, tu página de creador, Storelib Explore o un enlace de pago abierto por sí solo.",
 "Where each order was placed: your online store, Storelib (Explore, product and creator pages, communities), your OnePage or a checkout link.": "Dónde se hizo cada pedido: tu tienda online, Storelib (Explore, páginas de producto y de creador, comunidades), tu OnePage o un enlace de pago.",
 "Where each visit came from, judged by its first page: a search engine, a social app, an email, another website, or typed in directly.": "De dónde vino cada visita, según su primera página: un buscador, una red social, un correo, otro sitio web o escrita directamente.",
 "Where it came from": "De dónde viene",
