 "Where menus show": "Dónde aparecen los menús",
 "Where orders ship from": "Desde dónde se envían los pedidos",
 "Where parcels leave from. For your default location, it's also where return emails tell buyers to send items.": "Desde dónde salen los paquetes. En tu ubicación predeterminada, también es adonde los correos de devolución dicen que se envíen los artículos.",
 "Where people browse communities on Storelib.": "Donde la gente descubre comunidades en Storelib.",
