 "Where this period's money came from, less refunds: memberships and purchases, programs, event tickets. By plan: each plan by the name it is sold under, with the members paying for it at the end of the period.": "De dónde vino el dinero de este periodo, sin reembolsos: membresías y compras, programas, entradas a eventos. Por plan: cada plan con el nombre con que se vende y los miembros que lo pagan al final del periodo.",
