 "Your parcels are followed automatically": "Tus paquetes se siguen automáticamente",
 "Your payment went through. It opens here in a moment: refresh the page if it does not.": "Tu pago se realizó. Se abrirá aquí en un momento: actualiza la página si no lo hace.",
 "Your payment went through. The program opens in a moment: refresh the page if it does not.": "Tu pago se completó. El programa se abre en un momento: actualiza la página si no lo hace.",
 "Your payments account is disconnected and you set payments up again, on whichever account you like. It is the way to move to a different name, a business, or a different bank country.": "Tu cuenta de pagos se desconecta y vuelves a configurar los pagos, con la cuenta que quieras. Así se cambia a otro nombre, un negocio u otro país bancario.",
 "Your payout account needs attention": "Tu cuenta de cobro necesita atención",
 "Your payout account, plan and other businesses stay with you. They connect their own payouts.": "Tu cuenta de pagos, tu plan y tus otros negocios siguen contigo. La otra persona conecta sus propios pagos.",
 "Your personal info, a quick ID check with Stripe, then your bank. About five minutes.": "Tus datos personales, una verificación rápida de identidad con Stripe y luego tu banco. Unos cinco minutos.",
 "Your personal info, then your bank. About five minutes.": "Tus datos personales y luego tu banco. Unos cinco minutos.",
 "Your phone is shown to your payment provider and on order emails, so a buyer or a carrier can reach you about an order.": "Tu teléfono se muestra a tu proveedor de pagos y en los correos de pedidos, para que un comprador o un transportista pueda contactarte por un pedido.",
 "Your photo": "Tu foto",
 "Your picture fills the top of the page and fades into it.": "Tu imagen llena la parte superior de la página y se funde con ella.",
 "Your pictures": "Tus imágenes",
 "Your place kept in each lesson": "Tu progreso guardado en cada lección",
 "Your plan": "Tu plan",
 "Your plan will downgrade at the end of your current billing cycle. You'll keep all current features until then.": "Tu plan bajará al final de tu ciclo de facturación actual. Mantendrás todas las funciones actuales hasta entonces.",
 "Your plan, invoices and payment card": "Tu plan, facturas y tarjeta de pago",
 "Your posts are listed at {address}.": "Tus entradas aparecen en {address}.",
 "Your prices": "Tus precios",
 "Your prices ({currency})": "Tus precios ({currency})",
 "Your prices are in it and buyers pay in it. Payouts still arrive in your bank's currency.": "Tus precios están en ella y los compradores pagan en ella. Los pagos siguen llegando en la moneda de tu banco.",
 "Your prices are in {baseCurrency}. Cards are charged in {chargeCurrency}. A market in another currency shows an estimate converted at the European Central Bank's rate, and says so before payment.": "Tus precios están en {baseCurrency}. Las tarjetas se cobran en {chargeCurrency}. Un mercado en otra moneda muestra una estimación al tipo del Banco Central Europeo y lo indica antes del pago.",
 "Your prices, your website, the builder and checkout all use it.": "La usan tus precios, tu web, el editor y el pago.",
 "Your product has no stock yet. Add some so buyers can order it.": "Tu producto aún no tiene stock. Añade algo para que los compradores puedan pedirlo.",
 "Your products": "Tus productos",
 "Your products, pages, customers and orders stay as they are.": "Tus productos, páginas, clientes y pedidos siguen igual.",
 "Your products, pages, customers and orders stay exactly as they are. The Free fee applies to new sales, and the things only Pro has, like your own domain and hidden branding, stop at the end of your paid period.": "Tus productos, páginas, clientes y pedidos se quedan exactamente igual. La comisión de Gratis se aplica a las ventas nuevas, y lo que solo tiene Pro, como tu dominio propio y la marca oculta, se detiene al final de tu periodo pagado.",
 "Your profile name and photo, as they are now.": "Tu nombre y tu foto de perfil, tal como están ahora.",
 "Your profile photo, until you choose a logo.": "Tu foto de perfil, hasta que elijas un logotipo.",
 "Your profiles as a row of icons": "Tus perfiles como una fila de iconos",
 "Your programs and lessons, inside the community.": "Tus programas y lecciones, dentro de la comunidad.",
 "Your questions": "Tus preguntas",
 "Your rates go by weight, so without one they ship at the lightest price.": "Tus tarifas van por peso, así que sin él se envían al precio más ligero.",
 "Your rating and a link to it": "Tu valoración y un enlace",
