 "Your return window and the reasons a buyer can choose.": "Tu plazo de devolución y los motivos que puede elegir un comprador.",
 "Your role can review reports but not remove content.": "Tu rol puede revisar denuncias, pero no eliminar contenido.",
 "Your role in this community cannot do that.": "Tu rol en esta comunidad no puede hacer eso.",
 "Your sales show up here as soon as someone buys, with what they paid and what you keep.": "Tus ventas aparecen aquí en cuanto alguien compra, con lo que pagó y lo que te quedas.",
 "Your session ended. Sign in again to use Storelib AI.": "Tu sesión terminó. Inicia sesión de nuevo para usar Storelib AI.",
