 "Your shop doesn't charge tax yet.": "Tu tienda aún no cobra impuestos.",
 "Your shop's name comes from Store details, else your website.": "El nombre de tu tienda sale de Datos de la tienda o, si no, de tu sitio web.",
 "Your site still uses it. Change it in the builder, then send again.": "Tu sitio sigue usándolo. Cámbialo en el editor y vuelve a enviar.",
 "Your store": "Tu tienda",
