 "Your store has the essentials": "Tu tienda tiene lo esencial",
 "Your store is ready": "Tu tienda está lista",
 "Your store is set up": "Tu tienda está lista",
 "Your store logo.": "El logotipo de tu tienda.",
 "Your store name": "Nombre de tu tienda",
 "Your store opens in three steps": "Tu tienda abre en tres pasos",
 "Your store was not saved": "Tu tienda no se guardó",
 "Your store's contact email, from Settings › Store details. A buyer who answers an email writes to it.": "El correo de contacto de tu tienda, de Configuración › Datos de la tienda. Un comprador que responde a un correo te escribe ahí.",
 "Your store's country": "El país de tu tienda",
 "Your store's database is missing the blog's tables. Once SQL part 355 has been run, posts, categories and authors are kept here.": "A la base de datos de tu tienda le faltan las tablas del blog. Cuando se ejecute la parte SQL 355, las entradas, categorías y autores se guardarán aquí.",
 "Your store's name and contact details go on receipts, order emails and your checkout, so buyers know who they bought from.": "El nombre y los datos de contacto de tu tienda van en recibos, correos de pedidos y el pago, para que los compradores sepan a quién compraron.",
 "Your store, products, customers and details are removed. People who bought from you keep what they bought, and your sales and payout records are kept.": "Se eliminan tu tienda, productos, clientes y datos. Quienes te compraron conservan lo que compraron, y se guardan tus registros de ventas y transferencias.",
 "Your storelib.com addresses keep working. Once your website's domain is connected, its storelib.com address sends visitors there.": "Tus direcciones de storelib.com siguen funcionando. Cuando el dominio de tu sitio web esté conectado, su dirección de storelib.com enviará a los visitantes allí.",
 "Your store’s name as it is when the email is sent": "El nombre de tu tienda tal como es cuando se envía el correo",
 "Your stream, a video or a clip": "Tu directo, un video o un clip",
 "Your subscribers who said yes, and the orders of the last 90 days, in batches. A Brevo automation that starts when someone joins the list may run for them.": "Tus suscriptores que dijeron sí y los pedidos de los últimos 90 días, por lotes. Una automatización de Brevo que empieza cuando alguien entra en la lista puede ejecutarse para ellos.",
 "Your subscribers who said yes, and the orders of the last 90 days, in batches. A Kit automation that starts on the tag may run for them.": "Tus suscriptores que dijeron sí y los pedidos de los últimos 90 días, por lotes. Una automatización de Kit que empieza con la etiqueta puede ejecutarse para ellos.",
 "Your subscribers who said yes, and the orders of the last 90 days, in batches. A MailerLite automation that starts when someone joins the group may run for them.": "Tus suscriptores que dijeron sí y los pedidos de los últimos 90 días, por lotes. Una automatización de MailerLite que empieza cuando alguien entra en el grupo puede ejecutarse para ellos.",
 "Your subscribers who said yes, and the orders of the last 90 days, in batches. Past orders are sent as history, so no automation emails them again.": "Tus suscriptores que dijeron sí y los pedidos de los últimos 90 días, por lotes. Los pedidos anteriores se envían como historial, así que ninguna automatización les vuelve a escribir.",
